// Socket.IO 離線替代方案 - 用於內網環境
// 創建一個基本的 Socket.IO 兼容對象以防止 JavaScript 錯誤

(function() {
    'use strict';
    
    // 模擬 Socket.IO 客戶端
    function SocketIO(url, options) {
        this.connected = false;
        this.events = {};
        
        // 模擬連線延遲
        setTimeout(() => {
            console.log('Socket.IO 模擬模式：已連線');
            this.connected = true;
            this.emit('connect');
        }, 100);
        
        return this;
    }
    
    SocketIO.prototype.on = function(event, callback) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(callback);
        return this;
    };
    
    SocketIO.prototype.emit = function(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(callback => {
                try {
                    callback(data);
                } catch (e) {
                    console.error('Socket.IO 事件處理錯誤:', e);
                }
            });
        }
        
        // 模擬伺服器回應
        if (event === 'request_online_count') {
            setTimeout(() => {
                this.emit('online_count_update', { count: 1 });
            }, 50);
        }
        
        return this;
    };
    
    SocketIO.prototype.disconnect = function() {
        this.connected = false;
        this.emit('disconnect');
        return this;
    };
    
    // 全局 io 函數
    window.io = function(url, options) {
        return new SocketIO(url, options);
    };
    
    console.log('Socket.IO 離線替代方案已載入');
})();